/**
 *  View shape for the archive history view. `archive_exists` flags rows
 *  whose backup directory was deleted out-of-band (restore would fail; UI
 *  surfaces "delete permanently" as the only action).
 */
export type ArchivedWorkstreamView = {
	item: Workstream,
	/**  `<project>/archived-contexts/<slug>` — the on-disk backup path. */
	archivePath: string,
	archiveExists: boolean,
};

/**  Where a document lives within its root's layout. */
export type Area = 
/**  `<repos|global>/<…>/<user>/…` — a specific user's documents. */
{ kind: "user"; name: string } | 
/**  `<repos|global>/<…>/shared/…`. */
{ kind: "shared" } | 
/**  Anything outside the repos/global layout. */
{ kind: "other" };

/**  Binary statuses were re-probed (override set, redetect requested). */
export type BinariesChanged = null;

export type BinaryKind = "hyprlayer" | "claude" | "gh" | "git";

export type BinaryState = { state: "ok" } | { state: "missing" } | { state: "tooOld"; min: string };

export type BinaryStatus = {
	kind: BinaryKind,
	name: string,
	path: string | null,
	version: string | null,
	state: BinaryState,
	optional: boolean,
	overridden: boolean,
};

export type Bootstrap = {
	config: ConfigSummary,
	projects: Project[],
	binaries: BinaryStatus[],
	settings: AppSettings,
};

export type CheckStatus = "pass" | "warn" | "fail";

/**  The rolled-up state of the PR's CI checks, derived from `statusCheckRollup`. */
export type ChecksState = 
/**  No checks configured/reported for the head commit. */
"none" | 
/**  At least one check still queued or running. */
"pending" | 
/**  Every check completed successfully (or neutral/skipped). */
"passing" | 
/**  At least one check failed, errored, or timed out. */
"failing";

/**  Claude provider defaults. */
export type ClaudeSettings = {
	/**
	 *  Default model key for new sessions — one of the composer's model keys
	 *  (e.g. `"opus"`, `"sonnet"`) or a custom `--model` value. `None` keeps
	 *  the built-in default (Opus).
	 */
	defaultModel?: string | null,
	/**
	 *  Default reasoning-effort key for new sessions (`low`..`max`). `None`
	 *  keeps the built-in default (High).
	 */
	defaultEffort?: string | null,
	/**  Start new sessions in plan permission mode (`--permission-mode plan`). */
	defaultPlanMode?: boolean,
	/**
	 *  Which model keys appear in the composer's picker. `None` shows every
	 *  built-in model; `Some(list)` shows exactly those keys (presets plus any
	 *  custom model ids the user added).
	 */
	visibleModels?: string[] | null,
	/**  Default model for in-app code reviews. Reserved — no review feature yet. */
	reviewModel?: string | null,
	/**  Default effort for in-app code reviews. Reserved. */
	reviewEffort?: string | null,
	/**  Start new sessions in fast mode. Reserved — not a `claude` spawn flag yet. */
	defaultFastMode?: boolean,
};

/**
 *  Codex provider defaults. Stub — Codex isn't supported yet; this exists so
 *  the providers section round-trips and can grow fields without a migration.
 */
export type CodexSettings = {
	/**  Default model for new Codex sessions. Unused until Codex lands. */
	defaultModel?: string | null,
	/**  Personality/style for new Codex chats. Reserved — Codex isn't wired up. */
	personality?: string | null,
};

/**
 *  The hyprlayer CLI config file changed on disk (the CLI rewrote it, or the
 *  user edited it). Frontend should refetch bootstrap/project queries.
 */
export type ConfigChanged = null;

export type ConfigSummary = 
/**  No config file: first-run — onboarding should offer bootstrap. */
{ state: "missing"; path: string } | 
/**  Config exists but can't be used (parse error, future schema, ...). */
{ state: "error"; path: string; code: string; message: string; remedy: string | null } | { state: "ready"; path: string; user: string; backendKind: string; configured: boolean };

export type CreateDocInput = {
	/**  Repo path of the project the doc belongs to (None for global scope). */
	projectRepoPath: string | null,
	scope: string,
	docType: string,
	title: string,
	/**  Today's date from the user's locale, YYYY-MM-DD. */
	date: string,
	ticket: string | null,
	tags?: string[],
};

/**
 *  One immediate child of a directory in the "All Files" tree. `path` is
 *  relative to the worktree root (forward-slashed), suitable for the read/diff
 *  commands.
 */
export type DirEntry = {
	name: string,
	path: string,
	isDir: boolean,
};

export type DocContent = {
	meta: DocMeta,
	content: string,
	mtimeMs: number | null,
};

/**  Everything the UI needs to list and filter a document, sans body. */
export type DocMeta = {
	/**  Absolute path string — the canonical unique id. */
	id: string,
	/**  Path relative to its root, `/`-separated on every platform. */
	relPath: string,
	/**  Mapped repo name when the doc lives under `<repos_dir>/<name>/…`. */
	project: string | null,
	area: Area,
	/**
	 *  `"user" | "shared" | "global"` derived from the path; for
	 *  [`Area::Other`] falls back to `fm.scope` or `"shared"`.
	 */
	scope: string,
	/**  Profile that owns the root, `None` for the default backend. */
	profile: string | null,
	/**  `"git" | "obsidian"`. */
	backend: string,
	fm: Frontmatter,
	fmWarnings: string[],
	mtimeMs: number | null,
	sizeBytes: number | null,
};

/**  What sort of app an entry is, so the menu can group/label sensibly. */
export type EditorKind = 
/**  The OS file manager (Finder / Explorer / default handler). */
"files" | "editor" | "terminal";

/**
 *  One installed app the user can open a directory in. `openWith` is the value
 *  the frontend passes to `openPath(dir, openWith)`; `None` means "open with
 *  the OS default handler for a directory" (the file manager). `iconDataUrl` is
 *  a `data:image/png` of the app's real icon when we could rasterize one.
 */
export type EditorTarget = {
	id: string,
	name: string,
	kind: EditorKind,
	openWith: string | null,
	iconDataUrl: string | null,
};

/**  How a claude process ended. */
export type ExitOutcome = 
/**  Emitted a terminal `result` then exited 0. */
"completed" | 
/**  Stopped after an app-initiated interrupt. */
"interrupted" | 
/**  Exited without a terminal `result` (or non-zero) — treated as a crash. */
"crashed" | 
/**  We killed the process tree (hard stop / cleanup). */
"killed" | 
/**  Failed to spawn / disappeared immediately. */
"spawn_failed";

/**
 *  The two texts a CodeMirror merge view diffs. The frontend computes the diff,
 *  so we hand it whole-file contents rather than a patch. The `*_exists` flags
 *  distinguish an empty file from an absent one (added/deleted), which the
 *  viewer uses to force unified mode.
 */
export type FileSides = {
	original: string,
	modified: string,
	originalExists: boolean,
	modifiedExists: boolean,
};

export type FmPatchDto = {
	set?: FmSetEntry[],
	remove?: string[],
};

export type FmSetEntry = {
	key: string,
	value: FmValueDto,
};

export type FmValueDto = { kind: "str"; value: string } | { kind: "list"; values: string[] } | { kind: "null" };

/**
 *  The 10-field thought schema (hyprlayer-cli/src/backends/schema.rs), all
 *  optional because the parser must tolerate anything.
 */
export type Frontmatter = {
	title?: string | null,
	type?: string | null,
	date?: string | null,
	status?: string | null,
	ticket?: string | null,
	project?: string | null,
	scope?: string | null,
	tags?: string[],
	author?: string | null,
	related?: string[],
	/**
	 *  Unknown keys, preserved for display and round-tripping.
	 *  Unknown keys in display form: strings as-is, everything else compact
	 *  JSON, null as "". Read-only context for the UI — the line-surgical
	 *  patcher preserves the underlying bytes regardless. (Stringified
	 *  because specta forbids serde_json::Value's i64 arm in IPC types.)
	 */
	extra?: { [key in string]: string },
};

/**
 *  One changed file within a worktree, as it appears in the staged or unstaged
 *  list. `change` is one of: added | modified | deleted | renamed | untracked |
 *  typechange | conflict.
 */
export type GitFileEntry = {
	path: string,
	change: string,
};

/**  User-tunable git behaviour. Surfaced in Settings → Git. */
export type GitSettings = {
	/**
	 *  Branch-name prefix for new worktrees. `None` keeps the built-in
	 *  `hyprlayer/` default; a value (e.g. `"feature/"`) is used verbatim.
	 */
	branchPrefix?: string | null,
	/**
	 *  Delete the local branch when archiving a workspace. Default `true`,
	 *  matching the historical behaviour.
	 */
	deleteBranchOnArchive?: boolean,
	/**  Auto-archive a workspace once its PR is observed merged. */
	archiveOnMerge?: boolean,
	/**
	 *  Queue a GitHub auto-merge (`gh pr merge --auto`) so the PR lands once
	 *  required checks pass. Requires auto-merge enabled on the repo.
	 */
	automerge?: boolean,
	/**
	 *  Strip git-ignored files (build output, deps) from a worktree before
	 *  archiving so archives don't balloon. Files matched by the repo's
	 *  `worktree.copy` patterns are preserved. Default `true`.
	 */
	pruneIgnoredOnArchive?: boolean,
};

/**  One of the user's GitHub repos, for the clone dialog's "Recent repos" list. */
export type GithubRepo = {
	nameWithOwner: string,
	description?: string | null,
	url: string,
};

export type HealthCheck = {
	id: string,
	label: string,
	status: CheckStatus,
	detail: string | null,
	remedy: string | null,
};

export type HealthReport = {
	checks: HealthCheck[],
};

/**
 *  User overrides for keyboard shortcuts. Surfaced in Settings → Keyboard.
 * 
 *  Only *overrides* live here — the per-OS defaults are owned by the frontend
 *  catalog so they can change without a settings migration. Keys are stable
 *  command ids (e.g. "nav.dashboard"); a `Some(chord)` is a custom binding,
 *  `None` means the command is explicitly unbound, and an absent key means
 *  "use the catalog default".
 */
export type KeybindingSettings = {
	overrides?: { [key in string]: string | null },
};

export type LinkStatus = 
/**  Links exist and resolve. */
"ok" | 
/**  Backend has no filesystem tree (notion/anytype) — nothing to link. */
"unsupported" | 
/**  Links missing or broken. */
"broken";

/**  How the Merge button merges — picked per-PR by the user. */
export type MergeMethod = "squash" | "merge" | "rebase";

/**
 *  GitHub's mergeability verdict for the PR, from `gh`'s `mergeable` field.
 *  Distinguishes a clean merge from a conflicting branch — which we surface as a
 *  row in the checks panel — and from GitHub's transient `UNKNOWN` (still being
 *  computed server-side).
 */
export type MergeableState = 
/**  No conflicts — the PR can merge cleanly. */
"mergeable" | 
/**  The branch conflicts with its base and must be resolved before merging. */
"conflicting" | 
/**  GitHub hasn't finished computing mergeability yet (transient). */
"unknown";

/**
 *  Controls native OS notifications fired when a session moves into the
 *  needs-you state (awaiting permission/question) while the window is
 *  unfocused. The frontend reads this on every transition; toggling the
 *  setting takes effect on the next event without a restart.
 */
export type NotificationSettings = {
	/**
	 *  Master switch. `true` (default) fires a toast when an agent needs you;
	 *  `false` suppresses all notifications regardless of `sound`.
	 */
	enabled?: boolean,
	/**  Whether the toast plays the OS default notification sound. */
	sound?: boolean,
};

/**  One CI check on the PR's head commit, for the per-check breakdown popover. */
export type PrCheck = {
	name: string,
	/**  Per-check outcome — only `Pending`/`Passing`/`Failing` (never `None`). */
	state: ChecksState,
	/**  Link to the check's run/details page, when GitHub provides one. */
	url: string | null,
};

/**  Open/merged/closed — the PR's lifecycle state from `gh`'s `state` field. */
export type PrState = "open" | "merged" | "closed";

/**  A branch's pull request as the PR status bar renders it. */
export type PrStatus = {
	number: number,
	url: string,
	title: string,
	state: PrState,
	/**
	 *  GitHub reports the PR cleanly mergeable (no conflicts). True only for
	 *  `MERGEABLE`; the Merge button gates on this.
	 */
	mergeable: boolean,
	/**
	 *  GitHub's full mergeability verdict. Carries the `CONFLICTING` distinction
	 *  `mergeable` discards, so the checks panel can show a merge-conflict row.
	 */
	mergeableState: MergeableState,
	checks: ChecksState,
	checksTotal: number,
	checksPassed: number,
	checksFailed: number,
	/**  The individual checks, for the "which ran?" breakdown popover. */
	checksList: PrCheck[],
	/**
	 *  `APPROVED` | `CHANGES_REQUESTED` | `REVIEW_REQUIRED`, or None when the PR
	 *  requires no review / has no decision yet.
	 */
	reviewDecision: string | null,
};

/**
 *  A workstream's PR status changed server-side — it merged, its checks
 *  settled, or a PR appeared/disappeared for the branch. The backend PR watcher
 *  (`crate::pr_watch`) diffs each poll and emits this only on a real change; the
 *  frontend refetches that workstream's PR query so the merge/archive bar stays
 *  in sync without the UI polling `gh` on a timer.
 */
export type PrStatusChanged = {
	workstreamId: string,
};

export type Project = {
	/**  Absolute path of the app-owned clone (`~/hyprlayer/repos/<name>`). */
	path: string,
	/**  Human-facing project name (the app registry name, e.g. `brightblock.ai`). */
	mappedName: string,
	/**
	 *  The thoughts `repoMappings` key this repo resolves to — the identifier
	 *  docs are indexed (and worktrees created) under. The CLI sanitizes it, so
	 *  it can differ from `mapped_name` (e.g. `brightblock.ai` → `brightblock_ai`).
	 *  Filter docs by project using THIS, not the display name.
	 */
	thoughtsProject: string,
	profile: string | null,
	backendKind: string,
	existsOnDisk: boolean,
	/**  The git source this clone tracks; None for a local-only repo. */
	originUrl: string | null,
	/**  `clone` | `disk` — how it was added. */
	source: string,
};

export type ProjectDetail = {
	project: Project,
	storage: StorageInfo,
	thoughtsRoot: string | null,
};

/**
 *  Defaults for each agent provider. Claude is the only working provider
 *  today; Codex is stubbed so the section can render now and gain real
 *  fields later without a settings migration.
 */
export type ProviderSettings = {
	/**  Anthropic Claude (the `claude` CLI). */
	claude?: ClaudeSettings,
	/**
	 *  OpenAI Codex — not wired up yet; reserved so the providers section is
	 *  stable as we build it out.
	 */
	codex?: CodexSettings,
};

export type QueryResult = {
	/**  Matches before limit/offset. */
	total: number,
	items: DocMeta[],
};

/**
 *  One field of the 10-field thought metadata schema
 *  (`hyprlayer-cli/src/backends/schema.rs`).
 */
export type SchemaFieldInfo = {
	name: string,
	kind: string,
	options?: string[] | null,
	required: boolean,
};

export type SeedError = {
	entry: string,
	message: string,
};

export type SeedReport = {
	/**  Repo-relative file paths actually written into the new worktree. */
	copied: string[],
	/**  Entries (literal or glob) that matched nothing in the repo. */
	missing: string[],
	/**  Per-entry copy/compile errors that did not prevent other entries from being copied. */
	errors: SeedError[],
};

export type Session = {
	id: string,
	workstreamId: string,
	stage: string,
	/**  claude's own session id (set on the init event; drives `--resume`). */
	claudeSessionId: string | null,
	cwd: string,
	/**
	 *  starting | running | awaiting_permission | awaiting_question | completed |
	 *  interrupted | crashed | killed | spawn_failed
	 */
	state: string,
	model: string | null,
	/**  Cumulative cost reported by the latest `result` event. */
	costUsd: number | null,
	startedAt: number | null,
	endedAt: number | null,
	exitSummary: string | null,
};

/**
 *  One event in a session's lifetime. Ordered; the sequence per session is
 *  monotonic. Serialized tagged so the frontend can switch on `kind`. Tool
 *  inputs are carried as compact JSON strings (not `serde_json::Value`) so the
 *  type exports cleanly through specta; the UI parses them for display.
 */
export type SessionEvent = 
/**  Session is up; claude assigned its own id (used for `--resume`). */
{ kind: "init"; claudeSessionId: string; model: string | null } | 
/**
 *  A user turn the app sent to claude. claude never echoes the human prompt
 *  on stdout (it's input), so the driver emits this itself purely so the turn
 *  is persisted and replays after a restart. It is NOT forwarded to the live
 *  UI (which already shows the message optimistically) — persist-only, so the
 *  live transcript isn't double-stamped. `stage` is the stage label for the
 *  session's opening prompt, else null (a follow-up).
 */
{ kind: "userMessage"; text: string; stage: string | null } | 
/**
 *  Streaming text delta (live typing). Coalesced into `AssistantText` on
 *  turn completion — the UI shows partials, then replaces with the final.
 */
{ kind: "partialText"; text: string; parentId: string | null } | 
/**  A completed assistant text block. */
{ kind: "assistantText"; text: string; parentId: string | null } | 
/**  A completed thinking block (shown collapsed). */
{ kind: "thinking"; text: string; parentId: string | null } | 
/**
 *  The agent invoked a tool. `input` is compact JSON. `parent_id` is the
 *  `Task` tool-use id when this runs inside a subagent (else null).
 */
{ kind: "toolUse"; id: string; name: string; input: string; parentId: string | null } | 
/**  Result of a tool the agent ran. */
{ kind: "toolResult"; toolUseId: string; content: string; isError: boolean; parentId: string | null } | 
/**
 *  Permission prompt — the UI renders an Allow/Deny card; reply via the
 *  driver's `respond_permission` with this `request_id`. `input` is compact
 *  JSON of the tool's arguments.
 */
{ kind: "permissionAsk"; requestId: string; toolName: string; input: string } | 
/**
 *  The agent invoked `AskUserQuestion` — rather than a yes/no permission
 *  gate, the UI renders the questions interactively above the composer and
 *  the user picks answers; reply via the driver's `answer_question` with this
 *  `request_id`. `questions` is compact JSON of the `questions` array (each:
 *  `question`/`header`/`multiSelect`/`options[]{label,description}`).
 */
{ kind: "questionAsk"; requestId: string; questions: string } | 
/**
 *  A live context-window reading (input tokens in context), emitted per
 *  assistant message so the meter updates DURING a multi-tool turn — not
 *  only at `TurnDone`. Persisted (it's tiny) so the meter survives a restart
 *  even when a turn was interrupted before its `TurnDone` ever landed.
 */
{ kind: "usage"; contextTokens: number } | 
/**
 *  A turn finished; carries cumulative cost so far and the context-window
 *  fill (input tokens in context for the turn) for the UI's context meter.
 */
{ kind: "turnDone"; costUsd: number | null; numTurns: number | null; contextTokens: number | null } | 
/**
 *  claude auto- or manually compacted the conversation. The transcript
 *  renders a divider so a silent compaction stretch is legible instead of
 *  looking like a stuck turn. `trigger` is "auto" or "manual"; `pre_tokens`
 *  is the context fill just before the compact, when reported.
 */
{ kind: "compactBoundary"; trigger: string; preTokens: number | null } | 
/**
 *  A background shell task (spawned by `Bash{run_in_background:true}`) reached
 *  a terminal state. claude emits the underlying `task_notification`
 *  asynchronously the moment the shell finishes — even if the agent never
 *  polled it — so this is how the UI learns a fire-and-forget background task
 *  is done and drops it from the live "background tasks" indicator (the
 *  poll/stop paths miss the common case where the agent just moves on).
 *  `status` is "completed" or "failed"; `tool_use_id` is the spawning `Bash`
 *  call (the UI's direct transcript key), `task_id` the background shell id.
 */
{ kind: "backgroundTaskUpdate"; taskId: string; toolUseId: string | null; status: string } | 
/**  An unparseable / unknown stdout line — surfaced, never fatal. */
{ kind: "protocolError"; detail: string; raw: string } | 
/**  The process ended. Terminal: no further events for this session. */
{ kind: "exited"; outcome: ExitOutcome; code: number | null; stderrTail: string };

/**
 *  Coarse session state change, for board/sidebar badges (the fine-grained
 *  transcript flows over the per-session Channel, not this global event).
 */
export type SessionLifecycle = {
	sessionId: string,
	workstreamId: string,
	/**  Matches the `sessions.state` column. */
	state: string,
};

/**  One slash command offered in the composer's `/` autocomplete. */
export type SlashCommand = {
	/**  What the user types after `/`, e.g. `research_codebase`. */
	name: string,
	/**  One-line summary from the file's frontmatter (or first prose line). */
	description: string,
	/**  `project` | `user` — which `.claude` root supplied it (for the label). */
	source: string,
};

export type SortKey = 
/**  Text-match score; without `text` this falls through to `Date`. */
"relevance" | "date" | "mtime" | "title";

/**  Payload of `hyprlayer storage info --json`. */
export type StorageInfo = {
	backend: string,
	settings?: StorageSettings,
	projectPath?: string,
	mappedName?: string | null,
	profile?: string | null,
	user?: string | null,
	schema?: SchemaFieldInfo[],
};

/**
 *  Backend settings from `storage info --json`. The CLI emits a different
 *  key set per backend kind; this is the union, all optional.
 */
export type StorageSettings = {
	thoughtsRepo?: string | null,
	reposDir?: string | null,
	globalDir?: string | null,
	vaultPath?: string | null,
	vaultSubpath?: string | null,
	contentRoot?: string | null,
	parentPageId?: string | null,
	databaseId?: string | null,
	spaceId?: string | null,
	typeId?: string | null,
	apiTokenEnv?: string | null,
};

/**  One persisted event, for replay into a freshly-attached UI Channel. */
export type StoredEvent = {
	/**  Monotonic per-session sequence (f64 for IPC; small integers in practice). */
	seq: number | null,
	kind: string,
	/**  The full `SessionEvent` JSON. */
	payload: string,
	createdAt: number | null,
};

export type SyncReport = {
	output: string,
};

/**  How multiple `tags` filters combine. */
export type TagMode = "and" | "or";

/**  One streamed terminal event. Output is base64 because PTY output is binary. */
export type TerminalEvent = { kind: "output"; data: string } | { kind: "exited"; code: number | null };

/**  A library query: filters AND across fields, OR within a field. */
export type ThoughtQuery = {
	text?: string | null,
	types?: string[],
	statuses?: string[],
	projects?: string[],
	scopes?: string[],
	authors?: string[],
	tags?: string[],
	tagMode?: TagMode,
	/**  Inclusive lexicographic bounds against `fm.date` (ISO dates sort). */
	dateFrom?: string | null,
	dateTo?: string | null,
	sort?: SortKey,
	limit?: number | null,
	offset?: number | null,
};

/**
 *  The thoughts index changed: docs were (re)indexed, removed, or the whole
 *  tree was rescanned. `ids` are absolute-path doc ids (empty on rescans).
 *  Open editors use this to detect external changes to their document.
 */
export type ThoughtsIndexUpdated = {
	kind: string,
	ids: string[],
};

/**
 *  Probe of the default `~/thoughts` location, so the wizard can pick a sensible
 *  initial mode: if it's already a git repo, default to "open from disk" and
 *  prefill the path; otherwise default to "create" at the same path.
 */
export type ThoughtsProbe = {
	/**  Absolute `~/thoughts` path (tilde expanded), for prefilling the field. */
	defaultPath: string,
	/**  Whether that path exists on disk. */
	exists: boolean,
	/**  Whether it's already a git repository. */
	isGitRepo: boolean,
};

export type ThoughtsRepoStatus = {
	branch: string | null,
	/**  Working-tree entries that differ from HEAD (staged + unstaged + untracked). */
	dirty: number,
	ahead: number,
	behind: number,
	hasRemote: boolean,
};

/**  How the user wants to set up their thoughts repository. */
export type ThoughtsSource = 
/**
 *  Clone a remote git repository (e.g. a private GitHub thoughts repo).
 *  `location` is where the clone is placed.
 *  When None, defaults to `~/thoughts`.
 */
{ mode: "clone"; url: string; 
/**
 *  Absolute path where the cloned repo will be placed.
 *  When None, defaults to `~/thoughts`.
 */
location: string | null } | 
/**  Use an existing local git repository. */
{ mode: "disk"; 
/**  Absolute path to the existing git repository. */
path: string } | 
/**  Initialise a fresh git repository at the given path. */
{ mode: "create"; 
/**  Absolute path where the new repo will be created. */
path: string };

export type Workstream = {
	id: string,
	projectPath: string,
	title: string,
	slug: string,
	branch: string,
	worktreePath: string,
	baseBranch: string,
	/**  general | research | plan | implement | validate | ship */
	stage: string,
	/**  active | archived */
	status: string,
	prNumber: number | null,
	createdAt: number | null,
	updatedAt: number | null,
	archivedAt: number | null,
};

/**
 *  Base-branch choices for the "new workstream" dialog: every local + remote
 *  branch, plus the auto-detected default the picker pre-selects.
 */
export type WorkstreamBases = {
	branches: string[],
	defaultBase: string,
};

export type WorkstreamDoc = {
	workstreamId: string,
	docPath: string,
	/**  research | plan | other */
	role: string,
};

export type WorkstreamView = {
	item: Workstream,
	git: WorktreeStatus,
	/**
	 *  Populated only by `create_workstream`: result of copying configured
	 *  untracked files into the new worktree. `null` on every other path.
	 */
	seed: SeedReport | null,
};

/**
 *  A worktree's working state split the way the panel renders it: what's in the
 *  index (staged) vs. what differs between index and working tree (unstaged). A
 *  partially-staged file legitimately appears in both lists.
 */
export type WorktreeGitStatus = {
	staged: GitFileEntry[],
	unstaged: GitFileEntry[],
};

export type WorktreeStatus = {
	exists: boolean,
	branch: string | null,
	/**  Tracked changes (staged + unstaged), excluding thoughts/. */
	dirty: number,
	/**  Added lines in the working-tree diff vs HEAD, excluding thoughts/. */
	additions: number,
	/**  Deleted lines in the working-tree diff vs HEAD, excluding thoughts/. */
	deletions: number,
	/**  Untracked files, excluding thoughts/ (informational only). */
	untracked: number,
	ahead: number,
	behind: number,
	thoughts: LinkStatus,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

